#' Write an HTML Report to Browse Station by Station
#'
#' @description
#' Write the results of [run_pipeline()] as a folder with `index.html` and
#' the plots (`img/`). Open `index.html` in a web browser:
#' - the first page is an overview: number of pigs, mean ADG, ADFI and FCR,
#'   the QC settings, the pigs to check (low confidence or removed) and a
#'   table of all stations;
#' - then one page per station: the growth plot ([plot_adg()]), the feed
#'   intake plot ([plot_adfi()]) and a table of its pigs with ADG, ADFI,
#'   FCR, status and the reason of a low confidence or removal.
#'
#' Turn the pages with the arrow keys (or Page Up / Page Down, Home, End),
#' the buttons or the list of stations; type a pig ID in the search box to
#' jump to its station. Printing the page (e.g. to PDF) prints every page.
#' The folder works offline and can be copied or zipped as a whole.
#'
#' @param x Result of [run_pipeline()].
#' @param path Folder to write to (created if needed). Existing files of an
#'   earlier report are overwritten.
#' @param title Title of the report. Default: station type and dates.
#' @param locations Stations to include. Default `NULL`: all.
#' @param dpi Resolution of the plots. Default 150 (sharp on screen, about
#'   a quarter of the file size of 300).
#' @param open Open the report in the web browser when done. Default
#'   `FALSE`.
#' @param verbose 0 (silent), 1 (summary and progress, default).
#' @param cores Number of CPU cores for drawing the plots (see
#'   [save_plots()]). Default 1.
#'
#' @return Invisibly, the path of `index.html`.
#' @export
#' @examples
#' res <- run_pipeline(nedap, verbose = 0)
#' dir <- file.path(tempdir(), "report")
#' write_report(res, dir)
#' # then open file.path(dir, "index.html") in a web browser
write_report <- function(x, path, title = NULL, locations = NULL, dpi = 150,
                         open = FALSE, verbose = 1, cores = 1) {
  local_verbose(verbose)
  if (!inherits(x, "ppt_pipeline")) {
    cli::cli_abort("{.arg x} must be the result of {.fn run_pipeline}.")
  }
  if (!is.character(path) || length(path) != 1L || !nzchar(path)) {
    cli::cli_abort("{.arg path} must be a folder name.")
  }
  ppt_step("Writing the HTML report")
  img <- file.path(path, "img")
  dir.create(img, recursive = TRUE, showWarnings = FALSE)

  pigs <- report_pigs(x)
  if (!is.null(locations)) pigs <- pigs[location %in% as.character(locations)]
  locs <- natural_order(unique(pigs$location))
  if (length(locs) == 0L) cli::cli_abort("No station to report.")

  # plots, one file per station
  pa <- plot_adg(x$adg, weight = x$weight, locations = locs, verbose = 0)
  pf <- plot_adfi(x$adfi, locations = locs, verbose = 0)
  both <- rbind(pa[, .(location = paste0(location, "_growth"), n_pigs, plot, kind = "adg", loc = location)],
                pf[, .(location = paste0(location, "_intake"), n_pigs, plot, kind = "adfi", loc = location)])
  sv <- save_plots(both, img, prefix = "station", suffix = "plot", dpi = dpi,
                   verbose = verbose, cores = cores)
  sv[, `:=`(kind = both$kind, loc = both$loc)]
  files <- lapply(c(adg = "adg", adfi = "adfi"), function(k) {
    s <- sv[kind == k & saved == TRUE]
    stats::setNames(basename(s$file), s$loc)
  })

  title <- title %||% report_title(x)
  html <- report_html(x, pigs, locs, files, title)
  out <- file.path(path, "index.html")
  writeLines(enc2utf8(html), out, useBytes = TRUE)
  ppt_done("Report of {length(locs)} station{?s} written to {.path {out}}")
  if (isTRUE(open)) utils::browseURL(normalizePath(out))
  invisible(out)
}

# One row per pig for the report: pigs with results and removed pigs.
report_pigs <- function(x) {
  p <- x$fcr$per_pig
  keep <- p[, .(responder, location,
                status = data.table::fifelse(is.na(fcr), "no_fcr",
                                             data.table::fifelse(fcr_flag %in% "ok", "ok", "low_confidence")),
                adg_type, adg, adfi, fcr, stage_days, coverage,
                note = data.table::fifelse(is.na(fcr_note), "", fcr_note))]
  rm <- x$removed
  if (!is.null(rm) && nrow(rm) > 0L) {
    rm <- unique(rm, by = "responder")[!responder %in% keep$responder]
    rm <- rm[, .(responder, location, status = "removed", adg_type = NA_character_,
                 adg = NA_real_, adfi = NA_real_, fcr = NA_real_, stage_days = NA_real_,
                 coverage = NA_real_, note = paste0(step, ": ", reason))]
    keep <- rbind(keep, rm)
  }
  keep[, location := as.character(location)]
  keep[, responder := as.character(responder)]
  keep[order(match(location, natural_order(unique(location))),
             match(responder, natural_order(unique(responder))))]
}

report_title <- function(x) {
  st <- toupper(attr(x$visits, "station") %||% "")
  d <- range(x$visits$date, na.rm = TRUE)
  paste0(trimws(paste(st, "testing station")), ", ", format(d[1]), " to ", format(d[2]))
}

html_esc <- function(x) {
  x <- as.character(x)
  x[is.na(x)] <- ""
  x <- gsub("&", "&amp;", x, fixed = TRUE)
  x <- gsub("<", "&lt;", x, fixed = TRUE)
  x <- gsub(">", "&gt;", x, fixed = TRUE)
  gsub("\"", "&quot;", x, fixed = TRUE)
}

# Number for a table cell: "" for NA.
html_num <- function(x, digits = 0) {
  out <- formatC(x, format = "f", digits = digits, big.mark = ",")
  out[is.na(x)] <- ""
  out
}

report_status_label <- c(ok = "ok", low_confidence = "low confidence",
                         removed = "removed", no_fcr = "no FCR")

# Table of the pigs of one station (or of several, with a station column).
report_pig_table <- function(d, page_of = NULL) {
  st <- !is.null(page_of)
  head <- paste0("<tr>", if (st) "<th>Station</th>",
                 "<th>Pig</th><th>Status</th><th>ADG type</th>",
                 "<th class=\"n\">ADG<br><small>g/d</small></th>",
                 "<th class=\"n\">ADFI<br><small>g/d</small></th>",
                 "<th class=\"n\">FCR</th>",
                 "<th class=\"n\">Stage<br><small>days</small></th>",
                 "<th class=\"n\">Coverage</th><th>Note</th></tr>")
  id <- html_esc(d$responder)
  pig <- if (st) {
    paste0("<a href=\"#p-", page_of[d$location], "\" data-page=\"", page_of[d$location],
           "\" data-pig=\"", id, "\">", id, "</a>")
  } else id
  rows <- paste0(
    "<tr class=\"s-", d$status, "\"", if (!st) paste0(" id=\"pig-", id, "\""), ">",
    if (st) paste0("<td>", html_esc(d$location), "</td>"),
    "<td class=\"id\">", pig, "</td>",
    "<td><span class=\"tag s-", d$status, "\">", report_status_label[d$status], "</span></td>",
    "<td>", html_esc(d$adg_type), "</td>",
    "<td class=\"n\">", html_num(d$adg), "</td>",
    "<td class=\"n\">", html_num(d$adfi), "</td>",
    "<td class=\"n\">", html_num(d$fcr, 2), "</td>",
    "<td class=\"n\">", html_num(d$stage_days), "</td>",
    "<td class=\"n\">", ifelse(is.na(d$coverage), "", paste0(round(100 * d$coverage), "%")), "</td>",
    "<td class=\"note\">", html_esc(d$note), "</td></tr>")
  paste0("<div class=\"scroll\"><table class=\"pigs\"><thead>", head, "</thead><tbody>",
         paste(rows, collapse = "\n"), "</tbody></table></div>")
}

# "mean +/- SD" of a numeric vector.
html_ms <- function(v, digits = 0) {
  v <- v[!is.na(v)]
  if (length(v) == 0L) return("&ndash;")
  paste0(html_num(mean(v), digits), if (length(v) > 1L) paste0(" &plusmn; ", html_num(stats::sd(v), digits)))
}

report_html <- function(x, pigs, locs, files, title) {
  page_of <- stats::setNames(seq_along(locs), locs)
  qc <- x$adg$settings
  n_st <- table(factor(pigs$status, levels = names(report_status_label)))
  ok <- pigs[status %in% c("ok", "low_confidence")]

  # ---- overview page
  card <- function(label, value, sub = "") {
    paste0("<div class=\"card\"><div class=\"label\">", label, "</div><div class=\"value\">",
           value, "</div><div class=\"sub\">", sub, "</div></div>")
  }
  cards <- paste0(
    "<div class=\"cards\">",
    card("Pigs", nrow(pigs), paste0(n_st[["ok"]], " ok &middot; ", n_st[["low_confidence"]],
                                    " low confidence &middot; ", n_st[["removed"]] + n_st[["no_fcr"]],
                                    " without FCR")),
    card("ADG", html_ms(ok$adg), "g/d, mean &plusmn; SD"),
    card("ADFI", html_ms(ok$adfi), "g/d, mean &plusmn; SD"),
    card("FCR", html_ms(ok$fcr, 2), "mean &plusmn; SD"),
    card("Stations", length(locs), paste0("stage ", qc$stage_range[1], "&ndash;", qc$stage_range[2], " kg")),
    "</div>")
  set_val <- function(v) html_esc(paste(as.character(v), collapse = ", "))
  settings <- c(
    "Stage" = paste0(qc$stage_range[1], "&ndash;", qc$stage_range[2], " kg"),
    "Weight outliers" = set_val(c(if (isTRUE(qc$weight_track)) "track", qc$weight_outlier)),
    "Growth curve" = set_val(qc$curve_model),
    "Curve extrapolation" = set_val(qc$curve_extrap %||% "curve"),
    "Feed intake imputation" = set_val(qc$impute_method %||% ""),
    "Package" = paste0("tidypptsda ", utils::packageVersion("tidypptsda"))
  )
  settings_html <- paste0("<dl class=\"settings\">",
                          paste0("<dt>", names(settings), "</dt><dd>", settings, "</dd>", collapse = ""),
                          "</dl>")
  chk <- pigs[status != "ok"]
  check_html <- if (nrow(chk) > 0L) {
    paste0("<h2>Pigs to check <span class=\"count\">", nrow(chk), "</span></h2>",
           report_pig_table(chk, page_of))
  } else "<h2>Pigs to check</h2><p class=\"muted\">None: every pig has an FCR of good confidence.</p>"
  by_loc <- pigs[, .(n = .N, n_ok = sum(status == "ok"), n_chk = sum(status != "ok"),
                     adg = mean(adg[status %in% c("ok", "low_confidence")], na.rm = TRUE),
                     adfi = mean(adfi[status %in% c("ok", "low_confidence")], na.rm = TRUE),
                     fcr = mean(fcr[status %in% c("ok", "low_confidence")], na.rm = TRUE)),
                 by = location][match(locs, location)]
  for (v in c("adg", "adfi", "fcr")) data.table::set(by_loc, which(is.nan(by_loc[[v]])), v, NA_real_)
  st_rows <- paste0("<tr><td class=\"id\"><a href=\"#p-", page_of[by_loc$location], "\" data-page=\"",
                    page_of[by_loc$location], "\">", html_esc(by_loc$location), "</a></td>",
                    "<td class=\"n\">", by_loc$n, "</td><td class=\"n\">", by_loc$n_ok, "</td>",
                    "<td class=\"n", ifelse(by_loc$n_chk > 0L, " warn", ""), "\">", by_loc$n_chk, "</td>",
                    "<td class=\"n\">", html_num(by_loc$adg), "</td><td class=\"n\">", html_num(by_loc$adfi),
                    "</td><td class=\"n\">", html_num(by_loc$fcr, 2), "</td></tr>")
  st_html <- paste0("<h2>Stations</h2><div class=\"scroll\"><table class=\"pigs\"><thead><tr>",
                    "<th>Station</th><th class=\"n\">Pigs</th><th class=\"n\">ok</th>",
                    "<th class=\"n\">To check</th><th class=\"n\">ADG</th><th class=\"n\">ADFI</th>",
                    "<th class=\"n\">FCR</th></tr></thead><tbody>", paste(st_rows, collapse = "\n"),
                    "</tbody></table></div>")
  overview <- paste0("<section class=\"page\" id=\"p-0\" data-title=\"Overview\">",
                     "<h1>Overview</h1>", cards, "<h2>Settings</h2>", settings_html,
                     check_html, st_html, "</section>")

  # ---- station pages
  fig <- function(file, cap) {
    if (is.na(file)) return("")
    src <- paste0("img/", utils::URLencode(file, reserved = TRUE))
    paste0("<figure><a href=\"", src, "\" target=\"_blank\" title=\"Open the full-size plot\">",
           "<img loading=\"lazy\" src=\"", src, "\" alt=\"", html_esc(cap), "\"></a>",
           "<figcaption>", cap, "</figcaption></figure>")
  }
  station_pages <- vapply(locs, function(l) {
    d <- pigs[location == l]
    b <- by_loc[location == l]
    sub <- paste0(b$n, " pig", if (b$n != 1L) "s", " &middot; ", b$n_ok, " ok",
                  if (b$n_chk > 0L) paste0(" &middot; <span class=\"warn\">", b$n_chk, " to check</span>"),
                  " &middot; ADG ", html_ms(d$adg[d$status %in% c("ok", "low_confidence")]),
                  " g/d &middot; ADFI ", html_ms(d$adfi[d$status %in% c("ok", "low_confidence")]),
                  " g/d &middot; FCR ", html_ms(d$fcr[d$status %in% c("ok", "low_confidence")], 2))
    paste0("<section class=\"page\" id=\"p-", page_of[[l]], "\" data-title=\"Station ", html_esc(l),
           "\" hidden><h1>Station ", html_esc(l), "</h1><p class=\"lead\">", sub, "</p>",
           fig(unname(files$adg[l]), "Growth: recorded weights, outliers, filled daily weight and the stage"),
           fig(unname(files$adfi[l]), "Daily feed intake: recorded, corrected and filled days"),
           "<h2>Pigs</h2>", report_pig_table(d), "</section>")
  }, "")

  nav <- paste0("<a href=\"#p-0\" data-page=\"0\" class=\"nav-item\">Overview</a>",
                paste0("<a href=\"#p-", page_of, "\" data-page=\"", page_of, "\" class=\"nav-item\">Station ",
                       html_esc(locs),
                       ifelse(by_loc$n_chk > 0L, paste0(" <span class=\"badge\" title=\"pigs to check\">",
                                                        by_loc$n_chk, "</span>"), ""),
                       "</a>", collapse = ""))
  pig_map <- paste0("{", paste0("\"", gsub("([\"\\\\])", "\\\\\\1", pigs$responder), "\":",
                                page_of[pigs$location], collapse = ","), "}")

  tpl <- report_template()
  repl <- c("{{TITLE}}" = html_esc(title), "{{NAV}}" = nav,
            "{{PAGES}}" = paste(c(overview, station_pages), collapse = "\n"),
            "{{PIGS}}" = pig_map, "{{NPAGES}}" = as.character(length(locs) + 1L),
            "{{DATE}}" = format(Sys.Date()))
  for (k in names(repl)) tpl <- gsub(k, repl[[k]], tpl, fixed = TRUE)
  tpl
}

